-- =============================================================================
-- Thalvior ERP · RBAC S1 权限底座（分片 S1）
-- 权威依据：/Coze/Drive/编程专家/p0-6-shipping/rbac-spec-1025/rbac-spec.md（v1.0 冻结规格）
-- 范围    ：建表 + 扩列 + 种子入库 + tenant_root() + 最小后端鉴权闭环 + seed_fee_accounts 越权修复
-- 幂等    ：本文件可重复执行，重复执行 2 次结果一致（无重复行、无重复约束、无重复策略）
-- 人工回放：psql -v ON_ERROR_STOP=1 -f 20261025_rbac_s1.sql -d postgres
--           （migrations/ 目录无自动 runner，必须人工回放）
-- 禁改    ：不批量替换业务表 RLS 谓词（tenant_root(auth.uid()) 全量替换留到下一片）
-- =============================================================================

begin;

-- #############################################################################
-- §1 · 建表（spec §7.2 DDL 草案）
-- #############################################################################

create table if not exists public.roles (
  id uuid primary key default gen_random_uuid(),
  key text not null unique,
  name text not null,
  name_en text not null,
  description text,
  rank integer not null default 50,
  scope text not null default 'tenant',
  is_builtin boolean not null default false,
  is_system boolean not null default false,
  tenant_id uuid references public.profiles(id),
  created_at timestamptz not null default now(),
  constraint roles_scope_ck check ((scope='platform' and tenant_id is null) or (scope='tenant' and tenant_id is null))
);

create table if not exists public.permissions (
  id uuid primary key default gen_random_uuid(),
  key text not null unique,
  module text not null,
  resource text not null,
  action text not null,
  name text not null,
  name_en text not null,
  group_code text not null,
  risk_level text not null default 'medium',
  scope_type text not null default 'route',
  scope_ref text,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  constraint permissions_key_ck check (key ~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$'),
  constraint permissions_uniq unique (module, resource, action),
  constraint permissions_risk_ck check (risk_level in ('low','medium','high','critical')),
  constraint permissions_scope_ck check (scope_type in ('route','table','endpoint','rpc'))
);

create table if not exists public.role_permissions (
  id uuid primary key default gen_random_uuid(),
  role_id uuid not null references public.roles(id) on delete cascade,
  permission_id uuid not null references public.permissions(id) on delete cascade,
  effect text not null default 'allow',
  created_at timestamptz not null default now(),
  constraint role_permissions_uniq unique (role_id, permission_id),
  constraint role_permissions_effect_ck check (effect in ('allow','deny'))
);

-- profiles 扩列（spec §7.2-4）
alter table public.profiles add column if not exists owner_id uuid references public.profiles(id);
alter table public.profiles add column if not exists is_sub_account boolean not null default false;
alter table public.profiles add column if not exists tenant_role text;
alter table public.profiles add column if not exists tenant_id uuid references public.profiles(id);

create index if not exists profiles_owner_idx on public.profiles (owner_id);
create index if not exists profiles_tenant_idx on public.profiles (tenant_id);
create index if not exists profiles_sub_account_idx on public.profiles (owner_id) where is_sub_account;

-- 【刻意不建】spec §7.2 提到的唯一索引 profiles_one_owner_per_tenant (owner_id) where owner_id is not null and is_sub_account
--   原因：该定义会让「每个租户只能有 1 个子账号」，与 spec §5（max_subaccounts ≤ 30）/§7.6 子账号状态机直接冲突，
--   且会在 S2 批量建子账号时触发唯一冲突。本片按 §7.2 的 profiles_owner_idx（非唯一）建普通索引，
--   正确约束留待 S2 与子账号邀请流程一并落地（见交付报告「spec 勘误与偏差」）。

-- sub_accounts 扩列（spec §7.2-5）：邀请激活所需列 + RBAC 角色绑定
alter table public.sub_accounts add column if not exists auth_user_id uuid references auth.users(id);
alter table public.sub_accounts add column if not exists role_id uuid references public.roles(id);
alter table public.sub_accounts add column if not exists invite_token text;
alter table public.sub_accounts add column if not exists invited_at timestamptz;
alter table public.sub_accounts add column if not exists activated_at timestamptz;
alter table public.sub_accounts add column if not exists last_login_at timestamptz;
alter table public.sub_accounts add column if not exists invited_by uuid references public.profiles(id);

do $$
begin
  if not exists (select 1 from pg_constraint where conname='sub_accounts_status_ck' and conrelid='public.sub_accounts'::regclass) then
    alter table public.sub_accounts add constraint sub_accounts_status_ck check (status in ('待激活','启用','停用','已离职'));
  end if;
end $$;

create unique index if not exists sub_accounts_auth_user_uniq on public.sub_accounts (auth_user_id) where auth_user_id is not null;
create unique index if not exists sub_accounts_invite_token_uniq on public.sub_accounts (invite_token) where invite_token is not null;
create unique index if not exists sub_accounts_tenant_email_uniq on public.sub_accounts (user_id, lower(email)) where status <> '已离职';
create index if not exists sub_accounts_user_idx on public.sub_accounts (user_id);
create index if not exists sub_accounts_role_idx on public.sub_accounts (role_id);

create table if not exists public.sub_account_permissions (
  id uuid primary key default gen_random_uuid(),
  sub_account_id uuid not null references public.sub_accounts(id) on delete cascade,
  permission_id uuid not null references public.permissions(id) on delete cascade,
  effect text not null default 'allow',
  granted_by uuid references public.profiles(id),
  created_at timestamptz not null default now(),
  constraint sub_account_permissions_uniq unique (sub_account_id, permission_id),
  constraint sub_account_permissions_effect_ck check (effect in ('allow','deny'))
);

create table if not exists public.sub_account_audit_log (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.profiles(id),
  actor_id uuid not null references public.profiles(id),
  sub_account_id uuid references public.sub_accounts(id),
  action text not null,
  target text,
  result text not null,
  detail jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint sub_account_audit_result_ck check (result in ('allow','deny','success','error'))
);

create index if not exists sub_account_audit_tenant_idx on public.sub_account_audit_log (tenant_id, created_at desc);
create index if not exists sub_account_audit_actor_idx on public.sub_account_audit_log (actor_id, created_at desc);
create index if not exists sub_account_permissions_sub_idx on public.sub_account_permissions (sub_account_id);
create index if not exists role_permissions_role_idx on public.role_permissions (role_id);

-- #############################################################################
-- §2 · 多租户归属函数 tenant_root()（spec §6.3 方案 A）
--   profiles.owner_id 指向租户根；owner_id 为 null 者自身即租户根
-- #############################################################################

create or replace function public.tenant_root(p_uid uuid)
returns uuid
language plpgsql stable security definer set search_path=public
as $$
declare
  v_cur uuid := p_uid;
  v_next uuid;
  v_depth integer := 0;
begin
  if v_cur is null then
    return null;
  end if;
  -- 最多向上追溯 8 层，防御异常数据导致的环
  loop
    exit when v_depth >= 8;
    select p.owner_id into v_next from public.profiles p where p.id = v_cur;
    exit when v_next is null or v_next = v_cur;
    v_cur := v_next;
    v_depth := v_depth + 1;
  end loop;
  return v_cur;
end $$;

create or replace function public.tenant_root()
returns uuid
language sql stable security definer set search_path=public
as $$
  select public.tenant_root(auth.uid())
$$;

comment on function public.tenant_root(uuid) is '返回 uid 所属租户根（profiles.owner_id 链）；owner_id 为空者自身即租户根。spec §6.3 方案 A';

-- #############################################################################
-- §3 · 权限判定核心 has_perm() / my_permissions()（spec §7.4）
--   优先级：平台超管 > 子账号 deny > 子账号 allow > 角色 deny > 角色 allow > 默认 deny
-- #############################################################################

create or replace function public.has_perm(p_key text)
returns boolean
language plpgsql stable security definer set search_path=public
as $$
declare
  v_uid uuid := auth.uid();
  v_owner uuid;
  v_tenant_role text;
  v_role_id uuid;
  v_perm_id uuid;
  v_role_allow boolean := false;
  v_role_deny boolean := false;
  v_sub_allow boolean := false;
  v_sub_deny boolean := false;
begin
  if v_uid is null or p_key is null then
    return false;
  end if;

  -- ① 平台超管绕过（profiles.role='admin'，沿用既有 has_role）
  if public.has_role(v_uid, 'admin') then
    return true;
  end if;

  select p.owner_id, p.tenant_role into v_owner, v_tenant_role
    from public.profiles p where p.id = v_uid;

  if v_owner is null then
    -- ② 租户主账号（owner）：按 spec §4.2 owner 行（内置 owner 角色；G18 后台不可见、G20/G21 仅 view）
    select r.id into v_role_id from public.roles r where r.key = 'owner' and r.is_builtin;
  else
    -- ③ 子账号：优先 sub_accounts.role_id，其次 profiles.tenant_role 回退
    select sa.role_id into v_role_id
      from public.sub_accounts sa
     where sa.auth_user_id = v_uid and sa.status = '启用';
    if v_role_id is null then
      select r.id into v_role_id from public.roles r where r.key = v_tenant_role and r.is_builtin;
    end if;
  end if;

  select p.id into v_perm_id from public.permissions p where p.key = p_key and p.is_active;
  if v_perm_id is null then
    return false;
  end if;

  if v_role_id is not null then
    select coalesce(bool_or(rp.effect = 'allow'), false),
           coalesce(bool_or(rp.effect = 'deny'), false)
      into v_role_allow, v_role_deny
      from public.role_permissions rp
     where rp.role_id = v_role_id and rp.permission_id = v_perm_id;
  end if;

  if v_owner is not null then
    select coalesce(bool_or(sp.effect = 'allow'), false),
           coalesce(bool_or(sp.effect = 'deny'), false)
      into v_sub_allow, v_sub_deny
      from public.sub_account_permissions sp
     where sp.permission_id = v_perm_id
       and sp.sub_account_id in (select sa.id from public.sub_accounts sa where sa.auth_user_id = v_uid);
  end if;

  -- 优先级判定
  if v_sub_deny then  return false; end if;
  if v_sub_allow then return true;  end if;
  if v_role_deny then return false; end if;
  return v_role_allow;
end $$;

create or replace function public.my_permissions()
returns setof text
language plpgsql stable security definer set search_path=public
as $$
declare
  v_uid uuid := auth.uid();
  v_owner uuid;
  v_tenant_role text;
  v_role_id uuid;
begin
  if v_uid is null then
    return;
  end if;

  if public.has_role(v_uid, 'admin') then
    return query select p.key from public.permissions p where p.is_active order by p.key;
    return;
  end if;

  select p.owner_id, p.tenant_role into v_owner, v_tenant_role
    from public.profiles p where p.id = v_uid;

  if v_owner is null then
    select r.id into v_role_id from public.roles r where r.key = 'owner' and r.is_builtin;
  else
    select sa.role_id into v_role_id
      from public.sub_accounts sa
     where sa.auth_user_id = v_uid and sa.status = '启用';
    if v_role_id is null then
      select r.id into v_role_id from public.roles r where r.key = v_tenant_role and r.is_builtin;
    end if;
  end if;

  return query
    select p.key
      from public.permissions p
     where p.is_active
       and ( (v_role_id is not null and exists (
                select 1 from public.role_permissions rp
                 where rp.role_id = v_role_id and rp.permission_id = p.id and rp.effect = 'allow'))
             or (v_owner is not null and exists (
                select 1 from public.sub_account_permissions sp
                 where sp.permission_id = p.id and sp.effect = 'allow'
                   and sp.sub_account_id in (select sa.id from public.sub_accounts sa where sa.auth_user_id = v_uid))) )
       and not exists (
                select 1 from public.sub_account_permissions sp
                 where sp.permission_id = p.id and sp.effect = 'deny'
                   and sp.sub_account_id in (select sa.id from public.sub_accounts sa where sa.auth_user_id = v_uid))
       and not exists (
                select 1 from public.role_permissions rp
                 where rp.role_id = v_role_id and rp.permission_id = p.id and rp.effect = 'deny')
     order by p.key;
end $$;

comment on function public.has_perm(text) is '唯一权威权限判定入口。平台超管 > 子账号 deny > 子账号 allow > 角色 deny > 角色 allow > 默认 deny。spec §7.4';

-- #############################################################################
-- §4 · profiles RBAC 列防篡改守卫
--   新增列若可被本人 UPDATE 篡改（把 owner_id 置空即“升级”为 owner），底座当场失效。
--   规则：owner_id / is_sub_account / tenant_role / tenant_id 变更 →
--         仅平台超管、租户根（对自己下属）或系统上下文（auth.uid() is null，服务端 service_role）允许。
-- #############################################################################

create or replace function public.trg_profiles_rbac_guard()
returns trigger
language plpgsql
as $$
begin
  if new.owner_id        is distinct from old.owner_id
     or new.is_sub_account is distinct from old.is_sub_account
     or new.tenant_role    is distinct from old.tenant_role
     or new.tenant_id      is distinct from old.tenant_id then
    if auth.uid() is not null
       and not public.has_role(auth.uid(), 'admin')
       and auth.uid() <> public.tenant_root(auth.uid()) then
      raise exception 'PERMISSION_DENIED: cannot modify RBAC columns of profiles'
        using errcode = '42501';
    end if;
  end if;
  return new;
end $$;

drop trigger if exists trg_profiles_rbac_guard on public.profiles;
create trigger trg_profiles_rbac_guard
  before update on public.profiles
  for each row execute function public.trg_profiles_rbac_guard();

-- 既有非子账号、非平台超管的 profiles 回填 tenant_role='owner'（新注册账号由注册流程写入）
update public.profiles
   set tenant_role = 'owner'
 where tenant_role is null
   and is_sub_account = false
   and role = 'tenant_user';

-- #############################################################################
-- §5 · RLS：新表全部显式启用 + 策略（spec §7.3 + R4）
-- #############################################################################

alter table public.roles enable row level security;
alter table public.permissions enable row level security;
alter table public.role_permissions enable row level security;
alter table public.sub_account_permissions enable row level security;
alter table public.sub_account_audit_log enable row level security;

-- roles：内置角色全员可读；租户自定义角色仅本租户可读
drop policy if exists roles_select_own on public.roles;
create policy roles_select_own on public.roles for select
  using (tenant_id is null or tenant_id = public.tenant_root(auth.uid()) or public.has_role(auth.uid(), 'admin'));

drop policy if exists roles_admin_write on public.roles;
create policy roles_admin_write on public.roles for all
  using (public.has_role(auth.uid(), 'admin') or (not is_builtin and tenant_id = public.tenant_root(auth.uid())))
  with check (public.has_role(auth.uid(), 'admin') or (not is_builtin and tenant_id = public.tenant_root(auth.uid())));

-- permissions：权限目录全员可读；仅平台超管可写
drop policy if exists permissions_select_all on public.permissions;
create policy permissions_select_all on public.permissions for select using (true);

drop policy if exists permissions_admin_write on public.permissions;
create policy permissions_admin_write on public.permissions for all
  using (public.has_role(auth.uid(), 'admin'))
  with check (public.has_role(auth.uid(), 'admin'));

-- role_permissions：随 roles 可见范围
drop policy if exists role_permissions_select on public.role_permissions;
create policy role_permissions_select on public.role_permissions for select
  using (exists (select 1 from public.roles r
                  where r.id = role_id
                    and (r.tenant_id is null or r.tenant_id = public.tenant_root(auth.uid()) or public.has_role(auth.uid(), 'admin'))));

drop policy if exists role_permissions_write on public.role_permissions;
create policy role_permissions_write on public.role_permissions for all
  using (public.has_role(auth.uid(), 'admin')
         or exists (select 1 from public.roles r where r.id = role_id and not r.is_builtin and r.tenant_id = public.tenant_root(auth.uid())))
  with check (public.has_role(auth.uid(), 'admin')
         or exists (select 1 from public.roles r where r.id = role_id and not r.is_builtin and r.tenant_id = public.tenant_root(auth.uid())));

-- sub_accounts：沿用既有策略，另加「子账号本人可见自己」
drop policy if exists sub_accounts_select_self on public.sub_accounts;
create policy sub_accounts_select_self on public.sub_accounts for select
  using (auth_user_id = auth.uid());

-- sub_account_permissions：随 sub_accounts 可见范围
drop policy if exists sub_account_permissions_select on public.sub_account_permissions;
create policy sub_account_permissions_select on public.sub_account_permissions for select
  using (exists (select 1 from public.sub_accounts sa
                  where sa.id = sub_account_id
                    and (sa.user_id = public.tenant_root(auth.uid()) or sa.auth_user_id = auth.uid()
                         or public.has_role(auth.uid(), 'admin'))));

drop policy if exists sub_account_permissions_write on public.sub_account_permissions;
create policy sub_account_permissions_write on public.sub_account_permissions for all
  using (public.has_role(auth.uid(), 'admin')
         or exists (select 1 from public.sub_accounts sa
                     where sa.id = sub_account_id and sa.user_id = public.tenant_root(auth.uid())))
  with check (public.has_role(auth.uid(), 'admin')
         or exists (select 1 from public.sub_accounts sa
                     where sa.id = sub_account_id and sa.user_id = public.tenant_root(auth.uid())));

-- sub_account_audit_log：租户可见；写入仅走 SECURITY DEFINER 内部函数（不开放给前端直写）
drop policy if exists sub_account_audit_select on public.sub_account_audit_log;
create policy sub_account_audit_select on public.sub_account_audit_log for select
  using (tenant_id = public.tenant_root(auth.uid()) or public.has_role(auth.uid(), 'admin'));

-- #############################################################################
-- §6 · 审计写入（内部 SECURITY DEFINER，不对外暴露）
-- #############################################################################

create or replace function public.rbac_write_audit(
  p_actor uuid,
  p_perm_key text,
  p_action text,
  p_result text,
  p_target text,
  p_detail jsonb default '{}'::jsonb
)
returns void
language plpgsql security definer set search_path=public
as $$
declare
  v_tenant uuid;
  v_sub uuid;
begin
  v_tenant := public.tenant_root(p_actor);
  if v_tenant is null then
    return;
  end if;
  select sa.id into v_sub from public.sub_accounts sa where sa.auth_user_id = p_actor limit 1;
     coalesce(p_detail, '{}'::jsonb) || jsonb_build_object('perm_key', p_perm_key));
exception when others then
  null;  -- 审计失败不阻断业务主流程
end $$;

-- #############################################################################
-- §7 · 订单模块鉴权试点（S1 端到端：查权限点 → 判断角色 → 允许/拒绝）
--   后端强制：PostgREST RPC 层判定，客户端无法绕过（与前端隐藏无关）
-- #############################################################################

create or replace function public.order_list_guarded(p_limit integer default 50, p_offset integer default 0)
returns setof public.orders
language plpgsql stable security definer set search_path=public
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED: order module requires login' using errcode = '42501';
  end if;
  if not public.has_perm('order.order.view') then
    perform public.rbac_write_audit(v_uid, 'order.order.view', 'order.list', 'deny', 'orders', jsonb_build_object('phase', 'guard'));
    raise exception 'PERMISSION_DENIED: order.order.view' using errcode = '42501';
  end if;
  return query
    select o.* from public.orders o
     where o.user_id = public.tenant_root(v_uid)
     order by o.created_at desc nulls last
     limit greatest(1, least(coalesce(p_limit, 50), 500))
     offset greatest(0, coalesce(p_offset, 0));
end $$;

create or replace function public.order_update_remark_guarded(p_order_id text, p_remark text)
returns jsonb
language plpgsql volatile security definer set search_path=public
as $$
declare
  v_uid uuid := auth.uid();
  v_hit text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED: order module requires login' using errcode = '42501';
  end if;
  if not public.has_perm('order.order.remark') then
    perform public.rbac_write_audit(v_uid, 'order.order.remark', 'order.remark', 'deny', p_order_id, jsonb_build_object('phase', 'guard'));
    raise exception 'PERMISSION_DENIED: order.order.remark' using errcode = '42501';
  end if;
  update public.orders o set remark = coalesce(p_remark, '')
   where o.id = p_order_id and o.user_id = public.tenant_root(v_uid)
  returning o.id into v_hit;
  if v_hit is null then
    raise exception 'ORDER_NOT_FOUND: %', p_order_id using errcode = 'P0002';
  end if;
  perform public.rbac_write_audit(v_uid, 'order.order.remark', 'order.remark', 'allow', v_hit, jsonb_build_object('phase', 'guard'));
  return jsonb_build_object('ok', true, 'order_id', v_hit, 'remark', coalesce(p_remark, ''));
end $$;

create or replace function public.order_update_status_guarded(p_order_id text, p_status text)
returns jsonb
language plpgsql volatile security definer set search_path=public
as $$
declare
  v_uid uuid := auth.uid();
  v_hit text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED: order module requires login' using errcode = '42501';
  end if;
  if not public.has_perm('order.order.edit') then
    perform public.rbac_write_audit(v_uid, 'order.order.edit', 'order.status', 'deny', p_order_id, jsonb_build_object('phase', 'guard'));
    raise exception 'PERMISSION_DENIED: order.order.edit' using errcode = '42501';
  end if;
  update public.orders o set status = p_status
   where o.id = p_order_id and o.user_id = public.tenant_root(v_uid)
  returning o.id into v_hit;
  if v_hit is null then
    raise exception 'ORDER_NOT_FOUND: %', p_order_id using errcode = 'P0002';
  end if;
  perform public.rbac_write_audit(v_uid, 'order.order.edit', 'order.status', 'allow', v_hit, jsonb_build_object('phase', 'guard', 'status', p_status));
  return jsonb_build_object('ok', true, 'order_id', v_hit, 'status', p_status);
end $$;

-- #############################################################################
-- §8 · seed_fee_accounts 越权写入修复（spec §11 · R2 高危项）
--   现状：SECURITY DEFINER + GRANT authenticated（且 EXECUTE 实际落在 PUBLIC/anon）
--         且未校验 p_user = auth.uid() → 任一登录用户可为他租户写入费账户（跨租户污染）
--   修复：① 校验调用者（p_user 必须是 auth.uid() 或其租户根 tenant_root(auth.uid())）
--         ② 收窄 EXECUTE 权限：REVOKE PUBLIC/anon，仅保留 authenticated
--   【前置·一次性】该函数原属主为 supabase_admin，postgres 无权 CREATE OR REPLACE / REVOKE。
--     首次回放前需用 supabase_admin 执行一次（执行后本文件即可反复回放）：
--       psql -U supabase_admin -d postgres \
--         -c "alter function public.seed_fee_accounts(uuid) owner to postgres;"
-- #############################################################################

create or replace function public.seed_fee_accounts(p_user uuid)
returns void
language plpgsql security definer set search_path=public
as $$
declare
  v_role text := current_setting('role', true);
begin
  -- ═══ 越权防护（R2 修复，spec §11）════════════════════════════════════════════
  --   p_user 必须落在调用者的租户范围内；否则任何登录用户都能给别的租户写费账户。
  --   允许的上下文：
  --     ① p_user = auth.uid()                       → 为自己写
  --     ② p_user = tenant_root(auth.uid())          → 为自己所属租户的租户根写（同租户内）
  --     ③ auth.uid() IS NULL 的系统上下文（auth.on_auth_user_created 触发器 /
  --        service_role 服务端 Edge Function / 直连数据库运维）—— 这些上下文本就有
  --        数据库写权限，不是跨租户越权面；保留以免打断注册链路（handle_new_user 调用本函数）。
  --   拒绝：anon 角色（EXECUTE 已从 anon/PUBLIC 收回）+ 跨租户用户上下文。
  if v_role = 'anon' then
    raise exception 'PERMISSION_DENIED: seed_fee_accounts is not available to anonymous callers'
      using errcode = '42501';
  end if;
  if auth.uid() is not null
     and p_user <> auth.uid()
     and p_user <> public.tenant_root(auth.uid()) then
    raise exception 'PERMISSION_DENIED: cannot seed fee accounts for another tenant'
      using errcode = '42501';
  end if;

  with c(code) as (values ('platform'),('logistics'),('marketing'),('finance'),('other')),
  cat as (select id, code from public.fee_categories)
  select p_user, cat.id, v.code, 'fee.account.' || v.code, v.allocatable, v.def_alloc, v.neg_allowed, v.sort
  from (values
    -- platform 平台费用
    ('platform.commission',        'platform', true,  'order_amount_ratio', true,  10),
    ('platform.category_commission','platform',true,  'order_amount_ratio', false, 11),
    ('platform.service_fee',       'platform', true,  'order_amount_ratio', true,  12),
    ('platform.subscription',      'platform', false, 'none',               false, 13),
    ('platform.listing_fee',       'platform', false, 'none',               false, 14),
    ('platform.other',             'platform', true,  'order_even',         false, 15),
    -- logistics 物流费用
    ('logistics.shipping_fee',     'logistics', true, 'sku_quantity_ratio', true,  20),
    ('logistics.first_leg',        'logistics', true, 'sku_quantity_ratio', false, 21),
    ('logistics.last_mile',        'logistics', true, 'sku_quantity_ratio', false, 22),
    ('logistics.warehouse',        'logistics', true, 'sku_quantity_ratio', false, 23),
    ('logistics.fba_fee',          'logistics', true, 'sku_quantity_ratio', false, 24),
    ('logistics.long_term_storage','logistics', true, 'sku_quantity_ratio', false, 25),
    ('logistics.packing',          'logistics', true, 'order_even',         false, 26),
    ('logistics.customs_clearance','logistics', true, 'order_amount_ratio', false, 27),
    -- marketing 营销费用
    ('marketing.ads',              'marketing', true, 'order_amount_ratio', false, 30),
    ('marketing.promotion_discount','marketing',true, 'order_amount_ratio', true,  31),
    ('marketing.flash_sale',       'marketing', true, 'order_amount_ratio', false, 32),
    ('marketing.coupon',           'marketing', true, 'order_amount_ratio', true,  33),
    ('marketing.affiliate',        'marketing', true, 'order_amount_ratio', false, 34),
    ('marketing.influencer',       'marketing', false,'none',               false, 35),
    ('marketing.other',            'marketing', true, 'order_amount_ratio', false, 36),
    -- finance 金融费用
    ('finance.payment_fee',        'finance', true, 'order_amount_ratio', false, 40),
    ('finance.withdrawal_fee',     'finance', false,'none',               false, 41),
    ('finance.fx_loss',            'finance', true, 'order_amount_ratio', false, 42),
    ('finance.refund_fee',         'finance', true, 'order_amount_ratio', true,  43),
    ('finance.return_handling',    'finance', true, 'order_amount_ratio', false, 44),
    ('finance.interest',           'finance', true, 'order_amount_ratio', false, 45),
    ('finance.other',              'finance', true, 'order_amount_ratio', false, 46),
    -- other 其他
    ('other.tariff',               'other', true, 'order_amount_ratio', false, 50),
    ('other.tax',                  'other', true, 'order_amount_ratio', true,  51),
    ('other.compensation',         'other', true, 'order_amount_ratio', true,  52),
    ('other.misc',                 'other', true, 'order_even',         false, 53)
  ) as v(code, cat_code, allocatable, def_alloc, neg_allowed, sort)
  join cat on cat.code = v.cat_code
  on conflict (user_id, code) do nothing;
end 
$$;

revoke all on function public.seed_fee_accounts(uuid) from public;
revoke all on function public.seed_fee_accounts(uuid) from anon;
grant execute on function public.seed_fee_accounts(uuid) to authenticated;

-- #############################################################################
-- §9 · 授权（grants）
-- #############################################################################

grant usage on schema public to anon, authenticated;
grant select on public.permissions to anon, authenticated;
grant select on public.roles to authenticated;
grant select on public.role_permissions to authenticated;
grant select on public.sub_accounts to authenticated;
grant select on public.sub_account_permissions to authenticated;
grant select on public.sub_account_audit_log to authenticated;

grant execute on function public.has_perm(text) to anon, authenticated;
grant execute on function public.my_permissions() to authenticated;
grant execute on function public.tenant_root(uuid) to authenticated;
grant execute on function public.tenant_root() to authenticated;
grant execute on function public.order_list_guarded(integer, integer) to authenticated;
grant execute on function public.order_update_remark_guarded(text, text) to authenticated;
grant execute on function public.order_update_status_guarded(text, text) to authenticated;

revoke all on function public.rbac_write_audit(uuid, text, text, text, text, jsonb) from public, anon, authenticated;
revoke all on function public.trg_profiles_rbac_guard() from public, anon, authenticated;


-- ==========================================================================
-- §10 · 种子：permissions（505 条）
-- ==========================================================================
-- ============================================================
-- RBAC S1 · permissions 种子数据（505 条）
-- 来源：permissions.csv（UTF-8 BOM）· 权威依据 rbac-spec.md §2.5 / §7.2
-- 幂等：on conflict (key) do update —— 重复执行结果一致
-- ============================================================



-- ==========================================================================
-- §11 · 种子：roles（8 个）
-- ==========================================================================
-- ============================================================
-- RBAC S1 · roles 种子数据（8 个内置角色，spec §4.1）
-- 幂等：on conflict (key) do update
-- ============================================================



-- ==========================================================================
-- §12 · 种子：role_permissions（矩阵展开）
-- ==========================================================================
-- ============================================================
-- RBAC S1 · role_permissions 种子数据（8 角色 × 21 组矩阵展开）
-- 展开规则见 spec §4.3：●=全量 allow / △○=仅 view allow / ◐=白名单逐点 allow / —=无 / 逐点=全 deny
-- 语义：表内仅存 allow 行，未命中即 deny（默认拒绝）
-- 幂等：on conflict (role_id, permission_id) do update
-- ============================================================

-- 角色 platform_admin：allow 505 条

-- 角色 owner：allow 461 条

-- 角色 ops_lead：allow 278 条

-- 角色 warehouse：allow 179 条

-- 角色 support：allow 75 条

-- 角色 finance：allow 165 条

-- 角色 viewer：allow 154 条

-- 角色 custom：allow 0 条


-- ==========================================================================
-- §13 · 回放后自检（幂等核对 / 数据可见性不变）
-- ==========================================================================

-- =============================================================================
-- 回放后自检（在迁移自身的同一事务内执行，禁止 begin/rollback，否则会回滚整个迁移）
-- =============================================================================

\echo '--- ① 种子行数核对 ---'
select 'permissions' t, count(*) n from public.permissions
union all select 'roles', count(*) from public.roles
union all select 'role_permissions', count(*) from public.role_permissions
union all select 'sub_account_permissions', count(*) from public.sub_account_permissions
union all select 'sub_account_audit_log', count(*) from public.sub_account_audit_log
order by 1;

\echo '--- ② 每个角色的 allow 条数（矩阵展开结果）---'
select r.key, r.name, r.rank, count(rp.id) as allow_rows
  from public.roles r left join public.role_permissions rp on rp.role_id = r.id and rp.effect='allow'
 group by r.key, r.name, r.rank order by r.rank desc, r.key;

\echo '--- ③ 权限组覆盖度（group_code × 权限数，合计须 = 505）---'
select group_code, count(*) from public.permissions group by group_code order by group_code;

\echo '--- ④ 新表 RLS 必须全部启用（spec R4）---'
select c.relname, c.relrowsecurity
  from pg_class c join pg_namespace n on n.oid=c.relnamespace
 where n.nspname='public'
   and c.relname in ('roles','permissions','role_permissions','sub_account_permissions','sub_account_audit_log')
 order by 1;

\echo '--- ⑤ tenant_root() 只读验证（不改任何业务表策略）---'
select p.id, u.email, p.role, p.owner_id, p.is_sub_account, p.tenant_role,
       public.tenant_root(p.id) as tenant_root,
       (public.tenant_root(p.id) = p.id) as is_root
  from public.profiles p left join auth.users u on u.id = p.id
 order by p.created_at;

\echo '--- ⑥ 数据可见性不变核对（与迁移前 00_baseline.sql 同口径）---'
set local role authenticated;
set local request.jwt.claim.sub = 'a623c6f4-32a8-4595-ba9d-500bf4112f2c';
set local request.jwt.claims = '{"sub":"a623c6f4-32a8-4595-ba9d-500bf4112f2c","role":"authenticated"}';
select 'admin@thalvior.test' as who, 'orders' t, count(*) n from public.orders
union all select 'admin@thalvior.test','products', count(*) from public.products
union all select 'admin@thalvior.test','inventory', count(*) from public.inventory
union all select 'admin@thalvior.test','fee_accounts', count(*) from public.fee_accounts
union all select 'admin@thalvior.test','waybills', count(*) from public.waybills
union all select 'admin@thalvior.test','notifications', count(*) from public.notifications;
reset role;

set local role authenticated;
set local request.jwt.claim.sub = 'd9bcfa20-88c1-446a-848b-3ead60d0056e';
set local request.jwt.claims = '{"sub":"d9bcfa20-88c1-446a-848b-3ead60d0056e","role":"authenticated"}';
select 'qa.vis@visaudit.test' as who, 'orders' t, count(*) n from public.orders
union all select 'qa.vis@visaudit.test','products', count(*) from public.products
union all select 'qa.vis@visaudit.test','inventory', count(*) from public.inventory
union all select 'qa.vis@visaudit.test','fee_accounts', count(*) from public.fee_accounts
union all select 'qa.vis@visaudit.test','waybills', count(*) from public.waybills
union all select 'qa.vis@visaudit.test','notifications', count(*) from public.notifications;
reset role;

\echo '--- ⑦ seed_fee_accounts 越权防护就位核对 ---'
select p.proname, p.prosecdef as security_definer, p.proowner::regrole as owner,
       p.proacl::text as acl
  from pg_proc p join pg_namespace n on n.oid=p.pronamespace
 where n.nspname='public' and p.proname='seed_fee_accounts';


commit;
